import { Component, ChangeDetectionStrategy, OnInit, signal, computed } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { MatIconModule } from '@angular/material/icon';
import { Title } from '@angular/platform-browser';
import { SettingsTabNavComponent } from '../../components/settings-tab-nav/settings-tab-nav.component';
import { NotificationService } from '../../../../shared/services/notification.service';

interface TimeRangeSetting {
  label: string;
  startTime: string;
  endTime: string;
  editing: boolean;
}

interface CalendarSetting {
  id: string;
  name: string;
  color: string;
  checked: boolean;
  account: string;
}

@Component({
  selector: 'app-settings-page',
  standalone: true,
  imports: [CommonModule, FormsModule, MatIconModule, SettingsTabNavComponent],
  templateUrl: './settings-page.component.html',
  styleUrls: ['./settings-page.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class SettingsPageComponent implements OnInit {
  timeRanges: TimeRangeSetting[] = [
    { label: 'ミーティング', startTime: '09:30', endTime: '19:00', editing: false },
    { label: '食事会', startTime: '19:00', endTime: '23:00', editing: false },
  ];

  /** 30分単位の時間オプション */
  timeOptions: string[] = this.generateTimeOptions();

  private generateTimeOptions(): string[] {
    const options: string[] = [];
    for (let h = 0; h < 24; h++) {
      options.push(`${String(h).padStart(2, '0')}:00`);
      options.push(`${String(h).padStart(2, '0')}:30`);
    }
    return options;
  }

  calendarSearch = signal('');
  calendars = signal<CalendarSetting[]>(this.generateMockCalendars());

  filteredCalendars = computed(() => {
    const q = this.calendarSearch().toLowerCase();
    if (!q) return this.calendars();
    return this.calendars().filter(c =>
      c.name.toLowerCase().includes(q) || c.account.toLowerCase().includes(q)
    );
  });

  checkedCount = computed(() => this.calendars().filter(c => c.checked).length);
  totalCount = computed(() => this.calendars().length);

  /** アカウント別にグループ化 */
  groupedCalendars = computed(() => {
    const filtered = this.filteredCalendars();
    const groups = new Map<string, CalendarSetting[]>();
    for (const cal of filtered) {
      const list = groups.get(cal.account) || [];
      list.push(cal);
      groups.set(cal.account, list);
    }
    return Array.from(groups.entries()).map(([account, items]) => ({ account, items }));
  });

  constructor(private titleService: Title, private notification: NotificationService) {}

  ngOnInit(): void {
    this.titleService.setTitle('基本設定 | 日程調整ツール"スケコン"');
  }

  toggleEdit(index: number): void {
    this.timeRanges[index].editing = !this.timeRanges[index].editing;
    if (!this.timeRanges[index].editing) {
      this.notification.success('時間帯設定を保存しました');
    }
  }

  toggleCalendar(id: string): void {
    this.calendars.update(cals =>
      cals.map(c => c.id === id ? { ...c, checked: !c.checked } : c)
    );
    this.notification.info('カレンダーの表示設定を変更しました');
  }

  selectAll(): void {
    const filtered = this.filteredCalendars();
    const ids = new Set(filtered.map(c => c.id));
    this.calendars.update(cals =>
      cals.map(c => ids.has(c.id) ? { ...c, checked: true } : c)
    );
    this.notification.info('すべてのカレンダーを選択しました');
  }

  deselectAll(): void {
    const filtered = this.filteredCalendars();
    const ids = new Set(filtered.map(c => c.id));
    this.calendars.update(cals =>
      cals.map(c => ids.has(c.id) ? { ...c, checked: false } : c)
    );
    this.notification.info('すべてのカレンダーの選択を解除しました');
  }

  onCalendarSearchInput(event: Event): void {
    this.calendarSearch.set((event.target as HTMLInputElement).value);
  }

  private generateMockCalendars(): CalendarSetting[] {
    // カレンダーページの MOCK_CALENDARS と同じデータを使用
    const calendarData: { id: string; name: string; color: string; owner: string }[] = [
      { id: 'cal-personal', name: '個人', color: '#ff9800', owner: '自分' },
      { id: 'cal-work', name: '仕事', color: '#1976d2', owner: '自分' },
      { id: 'cal-schecon', name: 'スケコン予定', color: '#4caf50', owner: '自分' },
      { id: 'cal-tanaka', name: '田中太郎', color: '#9c27b0', owner: '田中太郎' },
      { id: 'cal-holidays', name: '日本の祝日', color: '#9e9e9e', owner: 'その他' },
    ];

    return calendarData.map(cal => ({
      id: cal.id,
      name: cal.name,
      color: cal.color,
      checked: true,
      account: cal.owner,
    }));
  }
}
